def MinValue(node, alpha, beta):
    if len(node.children) == 0:
        return node
    node.value = 100000
    for child in node.children:
        temp = MaxValue(child, alpha, beta)
        if temp.value < node.value:
            node.value = temp.value
        if child.value <= alpha:
            return child
        if child.value < beta:
            beta = child.value
    return node

